17.query:
load "/lookups/cmdb_businessapp"
| summarize `Count` = count(), by:{`CMDB Tier` = business_criticality}
| fieldsAdd sortOrder = if(`CMDB Tier` == "Core Services", 1, 
    else: if(`CMDB Tier` == "Mission Critical", 2, 
    else: if(`CMDB Tier` == "Business Critical", 3, 
    else: if(`CMDB Tier` == "Business Essential", 4, 
    else: 5))))
| sort sortOrder asc
| fieldsRemove sortOrder

20.query:
load "/lookups/cmdb_businessapp"
| fields `Application` = name, AppShortName = short_name, owner = owned_by, `Business Unit` = dv_business_unit, tier = business_criticality, Status = dv_operational_status, cmdb_ci_key
| lookup [
    load "/lookups/cmdb_server"
    | summarize `CMDB Servers` = count(), by:{busapp_cmdb_ci_key}
  ], sourceField:cmdb_ci_key, lookupField:busapp_cmdb_ci_key, fields:{`CMDB Servers`}
| lookup [
    fetch dt.entity.host
    | fields id, entity.name
    | parse entity.name, """LD:hostname ('.' LD:domain)? EOS"""
    | limit 20000
    | lookup [load "/lookups/cmdb_server"], sourceField:hostname, lookupField:name, fields:{busapp_key = busapp_cmdb_ci_key}
    | filter isNotNull(busapp_key)
    | summarize dtHostCount = count(), by:{busapp_key}
  ], sourceField:cmdb_ci_key, lookupField:busapp_key, fields:{dtHostCount}
| filter isNull(dtHostCount)
| fieldsRemove dtHostCount, cmdb_ci_key
| fieldsAdd `CMDB Servers` = coalesce(`CMDB Servers`, 0)
| filter in(`Business Unit`, array($BusinessUnit))
| filter in(tier, array($Tier))
| filter in(Status, array($Status))
| sort `Application` asc

24.query:
load "/lookups/cmdb_businessapp"
| filter in(`name`, array($SelectedApplication))
| fieldsAdd app_key = cmdb_ci_key, `Application` = name
| lookup [
    load "/lookups/cmdb_server"
    | fields app_key = busapp_cmdb_ci_key, server_name = name
    | fieldsAdd server_name_lower = lower(server_name)
    | lookup [
        fetch dt.entity.host
        | fields id, entity.name
        | parse entity.name, """LD:hostname ('.' LD:domain)? EOS"""
        | fieldsAdd server_name_lower = lower(hostname)
        | lookup [
            fetch logs
            | summarize logCount = count(), by:{host_id = dt.entity.host}
          ], sourceField:id, lookupField:host_id, fields:{logCount}
        | lookup [
            fetch spans
            | summarize spanCount = count(), by:{host_id = dt.entity.host}
          ], sourceField:id, lookupField:host_id, fields:{spanCount}
        | lookup [
            timeseries cpu = avg(dt.host.cpu.usage), by:{host_id = dt.entity.host}
            | fieldsAdd metricEvidence = if(arraySize(arrayRemoveNulls(cpu)) > 0, then:1, else:0)
            | fields host_id, metricEvidence
          ], sourceField:id, lookupField:host_id, fields:{metricEvidence}
        | fieldsAdd
            traces = if(isNotNull(spanCount) AND spanCount > 0, then:"✅", else:"❌"),
            metrics = if(isNotNull(metricEvidence) AND metricEvidence == 1, then:"✅", else:"❌"),
            logs = if(isNotNull(logCount) AND logCount > 0, then:"✅", else:"❌"),
            quality = if(isNotNull(spanCount) AND spanCount > 0 AND isNotNull(metricEvidence) AND metricEvidence == 1 AND isNotNull(logCount) AND logCount > 0, then:"Complete", else:"Partial")
        | fields server_name_lower, traces, metrics, logs, quality
      ], sourceField:server_name_lower, lookupField:server_name_lower, fields:{traces, metrics, logs, quality}
  ], sourceField:app_key, lookupField:app_key, fields:{server_name, traces, metrics, logs, quality}
| filter in(`Application`, array($ApplicationName))
| fields `Application`, `Server` = server_name, Traces = traces, Metrics = metrics, Logs = logs, `Evidence Quality` = quality
| sort `Server` asc

28.query:
load "/lookups/cmdb_businessapp"
| filter in(`name`, array($SelectedApplication))
| fieldsAdd app_key = cmdb_ci_key, `Application` = name
| lookup [
    load "/lookups/cmdb_server"
    | fields app_key = busapp_cmdb_ci_key, server_name = name
    | fieldsAdd server_name_lower = lower(server_name)
    | lookup [
        fetch dt.entity.host
        | fields id, entity.name
        | parse entity.name, """LD:hostname ('.' LD:domain)? EOS"""
        | fieldsAdd server_name_lower = lower(hostname)
        | fields id, server_name_lower
      ], sourceField:server_name_lower, lookupField:server_name_lower, fields:{id}
  ], sourceField:app_key, lookupField:app_key, fields:{server_name, id}
| lookup [
    fetch dt.entity.service
    | fields service_id = id, service_name = entity.name, host_id = dt.entity.host
    | filter isNotNull(host_id)
    | lookup [
        timeseries
            error_rate = (sum(dt.service.request.count.server, filter: in(span.status, {"ERROR"})) / sum(dt.service.request.count.server)) * 100,
            p95_latency = percentile(dt.service.response_time, 95),
            by:{service_id}
      ], sourceField:service_id, lookupField:service_id, fields:{error_rate, p95_latency}
  ], sourceField:id, lookupField:host_id, fields:{service_name, error_rate, p95_latency}
| fieldsAdd
    error_rate = coalesce(round(error_rate, 2), 0),
    p95_latency = coalesce(round(p95_latency, 0), 0)
| filter in(`Application`, array($ApplicationName))
| summarize service_count = count(), by:{`Service` = service_name, `Error Rate %` = error_rate, `P95 Latency (ms)` = p95_latency}
| sort `Error Rate %` desc, `Service` asc
